    description: "扬子鳄体形短小粗壮，头骨扁平，吻部短而钝，背面覆盖成行的角质鳞片，呈暗褐色或灰褐色，腹面灰白，四肢短健，尾侧扁而有力。它是中国特有的鳄类，古称“鼍”，民间又叫“土龙”，化石记录可追溯到数千万年前，被视为鳄类中的“活化石”。\n\n野生扬子鳄栖息于长江下游的池塘、沼泽与稻田沟渠，多在夜间活动，捕食鱼、虾、螺、蛙及水生昆虫，冬季掘洞休眠。每年 6–7 月交配，雌鳄用植物枝叶堆筑巢穴，产卵约 10–30 枚，靠巢材自然发酵的温度孵化，幼鳄出壳后由母鳄照料。由于湿地围垦与非法捕猎，野生种群一度不足 200 条；中国自 20 世纪 80 年代起开展人工繁育与放归，安徽宣城、浙江长兴等地建立了保护区。",
