    description: "加拉帕戈斯象龟背甲长可达 1.2–1.5 米，雄性体重可逾 200 千克，是世界上体型最大的陆龟。它的背甲高高隆起如马鞍或圆顶，不同岛屿的种群形态各异：湿润高地多为圆顶甲，干旱低地多为马鞍形甲，后者便于抬头取食高处的仙人掌；四肢粗壮如象腿，颈部皮肤松弛。\n\n它仅生活在厄瓜多尔的加拉帕戈斯群岛，栖息于草地、灌丛和火山坡地，以青草、仙人掌、果实和腐肉为食，清晨沿固定路径寻找水洼，能长时间不饮水。每年旱季过后交配，雌龟在沙地掘洞产卵 2–16 枚，孵化期约 4–8 个月。19 世纪捕鲸船大量捕捉象龟取肉取油，加上外来山羊、老鼠的竞争与捕食，多个亚种灭绝或濒临灭绝；如今各岛开展圈养繁殖和外来种清除，部分种群正在恢复。",
    habitat: "加拉帕戈斯群岛的草地、灌丛、火山坡地与半干旱低地",
    distribution: "厄瓜多尔加拉帕戈斯群岛，不同岛屿分布不同亚种",
