    description: "绿树蟒体长 1.5–2 米，身体细长而粗壮，头部较大且与颈部区分明显，成体通体翠绿，背部常有一串白色或黄色的斑块，腹部淡黄绿色；幼体则呈鲜黄、橙红或红褐色，长大后逐渐变为绿色。它的尾巴具有很强的缠绕力，可以牢牢挂在树枝上。\n\n它分布于新几内亚岛、印度尼西亚部分岛屿和澳大利亚昆士兰北部的热带雨林，栖息于树冠层，夜间伏击鼠类、小型鸟类和蜥蜴，捕猎时会用身体前段悬空保持“S”形，等待猎物靠近后迅速出击。每年繁殖季雌蟒产卵 6–25 枚，盘在卵上孵卵，孵化期约 45–55 天。它因体色艳丽而成为受欢迎的宠物蟒，野外种群受国际公约保护，在中国属于外来物种。",
