    description: "棱皮龟体长可达 2–3 米，体重 250–700 千克，个别记录超过 900 千克，是现存最大的海龟。它没有坚硬的角质盾片，背甲由黑色革质皮肤覆盖，表面有 7 条纵向棱脊，棱脊之间呈蓝黑色，缀有白色或淡色斑点；四肢特化成巨大的桨状，前肢尤其发达。\n\n它广泛分布于全球热带、亚热带和温带海域，是最能适应寒冷水域的海龟，能潜入数百米深的海中捕食水母，也吃海鞘和鱼卵。雌龟每 2–3 年产卵一次，每窝约 80–100 枚，孵化期 55–70 天，幼龟出壳后自行入海。由于渔网误捕、塑料垃圾被误食（塑料袋酷似水母）、沙滩开发和盗猎龟卵，棱皮龟种群数量急剧下降，被列为易危物种，中国将其列为国家一级保护动物。",
