    description: "印度蟒体长 3–4 米，个别可超过 5 米，雌性大于雄性。身体粗壮，头颈分界明显，吻端有热敏感的唇窝；体色以淡黄褐或灰白为底，背部有大型黑褐色斑块，斑块边缘镶浅色，尾部呈黑白相间的斑纹，腹部黄白色。它行动稳健，善于攀爬和游泳。\n\n它分布于印度、巴基斯坦、斯里兰卡等南亚地区，栖息于森林、灌丛、河岸和农田附近，夜间活动，捕食鼠类、兔、鹿、鸟类等，靠缠绕使猎物窒息后整只吞下。每年 3–6 月繁殖，雌蟒产卵 20–50 枚，盘在卵上孵卵约 55–70 天。由于皮革贸易和宠物捕捉，野生印度蟒数量明显下降，被列为近危物种并列入国际公约附录 I，国际贸易受到严格限制。",
