    description: "赤链蛇体长 1–1.5 米，身体较细，头部略扁，吻端钝；体色以黑色或黑褐色为底，体表和体侧布满红色或橙红色的横斑与环纹，斑纹在体侧常呈断续状，“赤链”之名由此而来，腹部淡黄并带黑斑。它行动敏捷，常在夜间活动。\n\n它分布于中国大部分地区以及朝鲜半岛、日本和越南，栖息于农田、水沟、草地、石堆和村舍附近，夜间捕食鼠类、蛙类、鱼类和其他蛇类。它是卵生蛇类，雌蛇每次产卵 5–15 枚，孵化期约 40–60 天。赤链蛇对人基本无害，一般认为无毒或仅有微弱毒性，被咬通常只出现轻微红肿；它捕食鼠类，是农田中的益蛇，但常因花纹醒目而被误杀，遇到时不必惊慌。",
