    description: "束带蛇体长 0.5–1.2 米，身体细长，头部与颈部区分不明显；体色变化很大，通常以深绿、褐或黑色为底，背部有一条或数条纵向的黄色、白色或红色条纹，看起来像袜带，“束带蛇”之名由此而来，体侧还常带棋盘状斑点。\n\n它广泛分布于北美洲的草地、森林、湿地、农田和城市边缘，适应力极强，白天活动，捕食蚯蚓、蛙类、鱼类、昆虫和小型哺乳动物。它的体色因地区不同变化明显，通常是深色底上带浅色纵纹。它是卵胎生蛇类，雌蛇一次产下 10–40 条幼蛇。束带蛇无毒，是北美最常见的蛇类之一，常被用作生物学研究材料；它对控制害虫和小型啮齿动物有益，在中国属于外来物种，不可随意放生。",
