    description: "杰克逊变色龙体长 20–30 厘米，雄性大于雌性，最显著的特征是雄性的头部长有三只角：吻部两只、眼后一只，形似三角龙，“三角变色龙”之名由此而来；雌性通常只有很小的角或没有角。体色以鲜绿、黄绿为主，雄性的角呈黄褐色，身体两侧常带黄色条纹。\n\n它原产于肯尼亚和坦桑尼亚的山地森林，栖息于湿润的灌丛和树冠层，白天活动，捕食昆虫，靠弹舌捕猎。与多数变色龙不同，它是卵胎生，雌蜥妊娠约 5–6 个月后直接产下 10–30 只幼蜥。它因外形奇特被大量捕捉作为宠物，并被引入美国夏威夷等地形成入侵种群；目前野外种群尚较稳定，被列为无危物种，国际贸易受国际公约监管。",
