    description: "四爪陆龟是体型较小的陆龟，背甲长 13–25 厘米，体重 0.5–2 千克。背甲扁平、略呈圆形，盾片中央有黄褐色与黑色交错的斑纹，边缘略外翻；腹甲黄色，具黑色斑块。四肢粗壮呈圆柱状，前肢覆盖大鳞片，最显著的特征是四肢各只有四枚爪，不同于多数陆龟的五爪，因此得名“四爪陆龟”。\n\n它们分布于中亚的干旱草原与半荒漠，从里海东岸到中国新疆西北部，栖息于黄土丘陵、山前草原与砾石坡地。四爪陆龟是穴居性最强的陆龟之一，会挖掘深达一米的斜洞躲避夏季高温与冬季严寒，一年中休眠时间可长达八九个月，仅在春季和初夏活动。食性以草本植物为主，取食叶片、花、果实与嫩茎，偶尔吃昆虫与蜗牛。春季交配，每窝 2–5 枚卵，孵化期约 60–90 天。因宠物贸易与栖息地开垦，其种群持续下降。",
